SELECT  FROM metal_process r WHERE r.del_flag='0' AND r.factory_id IS NOT NULL AND r.factory_id=#{factoryId} AND r.process_name LIKE #{q.namePattern} ESCAPE '!'
AND r.process_type =#{q.processType}
AND r.create_time >=#{q.startTime}AND r.create_time <#{q.endExclusive} AND r.factory_id=#{q.factoryId} ORDER BY r.process_id ASC
